examples.template:
MonarchProse(style = style) {
    heading({{heading}}, level = 2)
    paragraph(
        buildAnnotatedString {
            append({{intro.before}})
            withLink(LinkAnnotation.Url("https://example.com", links)) { append({{intro.link}}) }
            append({{intro.between}})
            withStyle(SpanStyle(fontFamily = FontFamily.Monospace, background = chip)) { append({{intro.code}}) }
            append({{intro.after}})
        },
    )
    listItem({{list.0.text}})
    listItem({{list.1.text}})
    listItem({{list.2.text}})
    listItem({{list.2.items.0}}, depth = 1)
    listItem({{list.2.items.1}}, depth = 1)
    quote(AnnotatedString({{quote}}))
    code({{code}})
    heading({{subheading}}, level = 3)
    table(
        columns = listOf({{table.columns.0}}, {{table.columns.1}}, {{table.columns.2}}),
        rows = listOf(
            listOf({{table.rows.0.option}}, {{table.rows.0.default}}, {{table.rows.0.description}}),
            listOf({{table.rows.1.option}}, {{table.rows.1.default}}, {{table.rows.1.description}}),
        ),
    )
    rule()
    paragraph(
        buildAnnotatedString {
            append({{outro.before}})
            withStyle(SpanStyle(fontFamily = FontFamily.Monospace, background = chip)) { append({{outro.key}}) }
            append({{outro.middle}})
            withStyle(SpanStyle(background = mark)) { append({{outro.mark}}) }
            append({{outro.after}})
        },
    )
}

examples.code:
MonarchProse(style = style) {
    heading("Getting started", level = 2)
    paragraph(
        buildAnnotatedString {
            append("This guide covers the basics. Read the ")
            withLink(LinkAnnotation.Url("https://example.com", links)) { append("overview") }
            append(" first, then run ")
            withStyle(SpanStyle(fontFamily = FontFamily.Monospace, background = chip)) { append("npm install") }
            append(".")
        },
    )
    listItem("Create a project")
    listItem("Invite your team")
    listItem("Set up notifications")
    listItem("Email", depth = 1)
    listItem("Mobile", depth = 1)
    quote(AnnotatedString("Small steps every day add up."))
    code("const total = items.reduce((sum, i) => sum + i.price, 0);")
    heading("Options", level = 3)
    table(
        columns = listOf("Option", "Default", "Description"),
        rows = listOf(
            listOf("size", "base", "Base font size of the content."),
            listOf("measure", "true", "Limit the line length."),
        ),
    )
    rule()
    paragraph(
        buildAnnotatedString {
            append("Press ")
            withStyle(SpanStyle(fontFamily = FontFamily.Monospace, background = chip)) { append("Enter") }
            append(" to save. ")
            withStyle(SpanStyle(background = mark)) { append("Highlighted") }
            append(" text stands out.")
        },
    )
}

examples.setup:
val style = MonarchProseStyle(MonarchProseSize.Sm, limitLineLength = false)
val links = style.linkStyles()
val text = buildAnnotatedString {
    append("See the ")
    withLink(LinkAnnotation.Url("https://example.com/guide", links)) { append("billing guide") }
    append(" first.")
}

examples.code:
MonarchProse(style = style) {
    paragraph(text)
    quote(AnnotatedString("Faster than I expected."))
}

Column {
    Text("Getting started", style = style.headingStyle(2))
    Text("Create a workspace, then invite your team.", style = style.bodyStyle())
}
